/** The parcel is a capability into this ledger, not proof supplied by item NBT. */
@net.minecraftforge.fml.common.Mod.EventBusSubscriber(modid="coraline")
public final class SpecialDelivery {
    public static final net.minecraftforge.registries.RegistryObject<Item> PACKAGE=ModItems.ITEMS.register("sealed_delivery_package",Parcel::new);
    public static void init(){}
    public static class Parcel extends Item {
        Parcel(){super(new Properties().stacksTo(1));}
        @Override public Component getName(ItemStack stack){return Component.literal("Other Mother's Sealed Package");}
        @Override public boolean canFitInsideContainerItems(){return false;}
        @Override public InteractionResultHolder<ItemStack> use(Level l,Player p,InteractionHand h){if(p instanceof ServerPlayer owner)openClick(owner,p.getItemInHand(h));return InteractionResultHolder.sidedSuccess(p.getItemInHand(h),l.isClientSide);}
        @Override public void inventoryTick(ItemStack stack,Level l,net.minecraft.world.entity.Entity actor,int slot,boolean selected){if(actor instanceof ServerPlayer p){var s=OtherMotherLoop.scene(p);if(s==null||!valid(p,s,stack))stack.setCount(0);}}
    }
    public static OtherMotherDialogue.Pool pool(String category,OtherMotherWelcome.State state){return new OtherMotherDialogue.Pool("events/special_delivery/"+category+"/"+SecretDialogue.stateId(state),2);}
    public static List<OtherMotherDialogue.Pool> pools(){var all=new ArrayList<OtherMotherDialogue.Pool>();for(var category:List.of("invitation","completion","caught_opening"))for(var state:OtherMotherWelcome.State.values())all.add(pool(category,state));return all;}
    static List<OtherMotherDialogue.Pool> directorPools(){return pools().subList(0,10);}
    public static boolean active(ServerPlayer p){var s=OtherMotherLoop.active(p);return s!=null&&VisitEvents.type(s)==VisitEvents.Type.SPECIAL_DELIVERY&&s.loop.event.getBoolean("DeliveryPending");}
    public static boolean openedActive(ServerPlayer p){return active(p)&&OtherMotherLoop.scene(p).loop.event.getBoolean("DeliveryOpened");}
    static boolean preparePayload(ServerPlayer p,VisitData.Scene s){var eligible=SecretRegistry.ALL.values().stream().filter(secret->secret.severity()>=.75&&!s.loop.secrets.journal.contains(secret.id())&&!s.loop.secrets.issued.containsValue(secret.id())).toList();if(eligible.isEmpty())return false;var n=s.loop.event;n.putUUID("DeliveryId",UUID.randomUUID());n.putUUID("DeliveryRecipient",UUID.randomUUID());n.putLong("DeliverySeed",p.getRandom().nextLong());n.putString("DeliveryPayload",eligible.get(p.getRandom().nextInt(eligible.size())).id());n.putInt("DeliveryVisit",s.loop.visits);n.putBoolean("DeliveryPending",true);return true;}
    static boolean ready(VisitData.Scene s){return DeliveryRoute.ready(s)&&SecretRegistry.ALL.values().stream().anyMatch(secret->secret.severity()>=.75&&!s.loop.secrets.journal.contains(secret.id())&&!s.loop.secrets.issued.containsValue(secret.id()));}
    static boolean prepare(ServerPlayer p,VisitData.Scene s){if(!ready(s)||!preparePayload(p,s))return false;if(!DeliveryRoute.activatePrepared(p,s)){s.loop.event.putBoolean("DeliveryPending",false);DeliveryRoute.cleanup(p,s);return false;}s.loop.event.putString("DeliveryState","INTRO_DIALOGUE");resident(p,s);OtherMotherLoop.phase(p,s,EVENT_INTRO);return true;}
    static void begin(ServerPlayer p,VisitData.Scene s){var n=s.loop.event;n.putString("DeliveryState","TRAVEL_TO_RECIPIENT");OtherMotherLoop.phase(p,s,DELIVERY_ACTIVE);ensurePackage(p,s);}
    static boolean tick(ServerPlayer p,VisitData.Scene s){var n=s.loop.event;
        if(s.loop.phase==DELIVERY_PREPARING){String state=DeliveryRoute.tick(p,s);if(state.equals("FAILED")){n.putBoolean("DeliveryPending",false);VisitAudio.caption(p,"Other Mother","We'll do something else while the delivery route is prepared.",70);VisitEvents.fallback(p,s,VisitEvents.Type.SPECIAL_DELIVERY);}else if(state.equals("READY")){n.putString("DeliveryState","INTRO_DIALOGUE");resident(p,s);OtherMotherLoop.phase(p,s,EVENT_INTRO);}return true;}
        if(s.loop.phase==DELIVERY_ACTIVE){if(p.tickCount%20==0){ensurePackage(p,s);resident(p,s);routeFeedback(p,s);OtherMotherLoop.changed(p);}int elapsed=n.getInt("DeliveryElapsed")+1;n.putInt("DeliveryElapsed",elapsed);int limit=VisitConfig.DELIVERY_LIMIT.get();if(limit>0&&elapsed>=limit){n.putBoolean("DeliveryCancelled",true);n.putBoolean("DeliveryPending",false);VisitEvents.next(p,s,true);}return true;}
        if(s.loop.phase==DELIVERY_FINISH){if(!VisitEvents.speak(p,s,pool("completion",SecretDialogue.state(p))))return true;if(!n.getBoolean("CompletionAwarded")){n.putBoolean("CompletionAwarded",true);OtherMotherLoop.relationship(p,s.loop.trust+VisitConfig.DELIVERY_TRUST.get().floatValue(),s.loop.suspicion);if(!n.getBoolean("DeliveryOpened"))SecretTransactions.give(p,new ItemStack(Items.COOKIE,2));}n.putString("DeliveryState",n.getBoolean("DeliveryOpened")?"COMPLETED_UNDETECTED":"COMPLETED_HONESTLY");n.putBoolean("DeliveryResolved",true);n.putBoolean("DeliveryPending",false);SecretTransactions.checkpoint(p);VisitEvents.next(p,s,false);return true;}return true;
    }
    static boolean valid(ServerPlayer p,VisitData.Scene s,ItemStack stack){CompoundTag n=stack.getTag(),event=s.loop.event;return stack.is(PACKAGE.get())&&n!=null&&p.getUUID().equals(s.owner)&&VisitEvents.type(s)==VisitEvents.Type.SPECIAL_DELIVERY&&event.getBoolean("DeliveryPending")&&!event.getBoolean("DeliveryOpened")&&!event.getBoolean("DeliveryDelivered")&&!event.getBoolean("DeliveryResolved")&&n.hasUUID("DeliveryOwner")&&p.getUUID().equals(n.getUUID("DeliveryOwner"))&&n.hasUUID("DeliveryId")&&event.hasUUID("DeliveryId")&&event.getUUID("DeliveryId").equals(n.getUUID("DeliveryId"));}
    static ItemStack parcel(ServerPlayer p,VisitData.Scene s){var n=s.loop.event;var stack=new ItemStack(PACKAGE.get());var tag=stack.getOrCreateTag();tag.putUUID("DeliveryOwner",p.getUUID());tag.putUUID("DeliveryId",n.getUUID("DeliveryId"));tag.putUUID("RecipientId",n.getUUID("DeliveryRecipient"));tag.putString("SecretPayload",n.getString("DeliveryPayload"));tag.putInt("EventSerial",n.getInt("Serial"));tag.putInt("Visit",n.getInt("DeliveryVisit"));tag.putInt("WarningStage",n.getInt("DeliveryWarning"));return stack;}
    static void ensurePackage(ServerPlayer p,VisitData.Scene s){var n=s.loop.event;if(!n.getBoolean("DeliveryPending")||n.getBoolean("DeliveryOpened")||n.getBoolean("DeliveryDelivered")||n.getBoolean("DeliveryResolved"))return;boolean found=false;for(int i=0;i<p.getInventory().getContainerSize();i++){var stack=p.getInventory().getItem(i);if(!stack.is(PACKAGE.get()))continue;if(valid(p,s,stack)&&!found){stack.setCount(1);stack.getOrCreateTag().putInt("WarningStage",n.getInt("DeliveryWarning"));found=true;}else stack.setCount(0);}var carried=p.containerMenu.getCarried();if(carried.is(PACKAGE.get())){if(valid(p,s,carried)&&!found){found=true;carried.setCount(1);}else p.containerMenu.setCarried(ItemStack.EMPTY);}if(!found){for(int i=0;i<36;i++)if(p.getInventory().getItem(i).isEmpty()){p.getInventory().setItem(i,parcel(p,s));n.putBoolean("PackageGranted",true);SecretTransactions.checkpoint(p);return;}if(p.tickCount%200==0)p.displayClientMessage(Component.literal("Make room for Mother's sealed package."),true);}}
    static void removePackage(ServerPlayer p){for(int i=0;i<p.getInventory().getContainerSize();i++)if(p.getInventory().getItem(i).is(PACKAGE.get()))p.getInventory().setItem(i,ItemStack.EMPTY);if(p.containerMenu.getCarried().is(PACKAGE.get()))p.containerMenu.setCarried(ItemStack.EMPTY);p.getInventory().setChanged();p.containerMenu.broadcastChanges();}
    public static void openClick(ServerPlayer p,ItemStack stack){var s=OtherMotherLoop.active(p);if(s==null||s.loop.phase!=DELIVERY_ACTIVE||!valid(p,s,stack)||SecretDialogue.busy(p))return;var n=s.loop.event;long now=OtherMotherLoop.now(p);if(n.getBoolean("DeliveryAwaitRelease")||now<n.getLong("DeliveryClickAfter"))return;n.putBoolean("DeliveryAwaitRelease",true);n.putLong("DeliveryClickAfter",now+12);int stage=n.getInt("DeliveryWarning")+1;n.putInt("DeliveryWarning",stage);if(stage==1)p.sendSystemMessage(Component.literal("Other Mother told you not to open this package. Are you sure?"));else if(stage==2)p.sendSystemMessage(Component.literal("FINAL WARNING: Opening this package will remove your protection from Mother's spies. If she catches you, she'll know what you've done. Right-click again to open it."));else open(p,s);SecretTransactions.checkpoint(p);}
    public static void released(ServerPlayer p,UUID id){var s=OtherMotherLoop.scene(p);if(s!=null&&s.loop.event.hasUUID("DeliveryId")&&s.loop.event.getUUID("DeliveryId").equals(id))s.loop.event.putBoolean("DeliveryAwaitRelease",false);}
    static void open(ServerPlayer p,VisitData.Scene s){var n=s.loop.event;if(n.getBoolean("DeliveryOpened")||n.getBoolean("DeliveryDelivered")||n.getBoolean("DeliveryResolved"))return;n.putBoolean("DeliveryOpened",true);n.putBoolean("DeliveryProtected",false);n.putString("DeliveryState","PACKAGE_OPENED");removePackage(p);SecretTransactions.checkpoint(p);if(!n.getBoolean("DeliverySecretIssued")){n.putBoolean("DeliverySecretIssued",true);SecretTransactions.issue(p,n.getString("DeliveryPayload"));SecretTransactions.checkpoint(p);}p.serverLevel().playSound(null,p.blockPosition(),net.minecraft.sounds.SoundEvents.BUNDLE_REMOVE_ONE,net.minecraft.sounds.SoundSource.PLAYERS,.65F,.8F);p.serverLevel().sendParticles(p,net.minecraft.core.particles.ParticleTypes.ENCHANT,true,p.getX(),p.getY()+1,p.getZ(),16,.25,.2,.25,.02);VisitAudio.caption(p,"Opened parcel","Its secret is yours. Mother's watchers no longer ignore you.",100);}
    private record RouteIndex(Map<Long,List<BlockPos>> chunks,int serial){}
    private static final Map<UUID,RouteIndex> ROUTES=new HashMap<>();
    static double distance(ServerPlayer p,VisitData.Scene s){var cache=ROUTES.get(p.getUUID());if(cache==null||cache.serial!=s.loop.event.getInt("Serial")){var chunks=new HashMap<Long,List<BlockPos>>();for(var node:DeliveryRoute.nodes(s))chunks.computeIfAbsent(net.minecraft.world.level.ChunkPos.asLong(node.getX()>>4,node.getZ()>>4),k->new ArrayList<>()).add(node);cache=new RouteIndex(chunks,s.loop.event.getInt("Serial"));ROUTES.put(p.getUUID(),cache);}double distance=Double.MAX_VALUE;for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)for(var node:cache.chunks.getOrDefault(net.minecraft.world.level.ChunkPos.asLong((p.getBlockX()>>4)+x,(p.getBlockZ()>>4)+z),List.of()))distance=Math.min(distance,p.position().distanceTo(Vec3.atBottomCenterOf(node)));return distance;}
    public static boolean protectedRoute(ServerPlayer p){if(!active(p))return false;var s=OtherMotherLoop.scene(p);var n=s.loop.event;if(s.loop.secrets.searching()||s.loop.secrets.search==SecretsState.Search.CONFRONTING||n.getBoolean("DeliveryOpened")||n.getBoolean("DeliveryKnown")||n.getBoolean("DeliveryResolved")||s.loop.phase!=DELIVERY_ACTIVE)return false;if(!n.getBoolean("DeliveryDelivered")){boolean held=valid(p,s,p.containerMenu.getCarried());for(int i=0;i<p.getInventory().getContainerSize()&&!held;i++)held=valid(p,s,p.getInventory().getItem(i));if(!held)return false;}double margin=VisitConfig.DELIVERY_MARGIN.get()+(n.getBoolean("DeliveryProtected")?.75:0);return distance(p,s)<=margin;}
    static void routeFeedback(ServerPlayer p,VisitData.Scene s){var n=s.loop.event;boolean was=n.getBoolean("DeliveryProtected"),now=protectedRoute(p);n.putBoolean("DeliveryProtected",now);if(was==now||n.getBoolean("DeliveryOpened"))return;if(OtherMotherLoop.now(p)>=n.getLong("RouteHintAfter")){n.putLong("RouteHintAfter",OtherMotherLoop.now(p)+100);p.displayClientMessage(Component.literal(now?"Back on the delivery route.":"You've left the delivery route. Mother's watchers can see you again."),true);}}
    static ParentEntity resident(ServerPlayer p,VisitData.Scene s){var n=s.loop.event;var l=p.serverLevel();if(n.hasUUID("RecipientActor")&&l.getEntity(n.getUUID("RecipientActor")) instanceof ParentEntity actor)return actor;var c=DeliveryRoute.house(s);if(c==null)return null;var matches=l.getEntitiesOfClass(ParentEntity.class,new AABB(c).inflate(15),e->e.getPersistentData().hasUUID("DeliveryOwner")&&p.getUUID().equals(e.getPersistentData().getUUID("DeliveryOwner"))&&e.getPersistentData().getInt("DeliverySerial")==n.getInt("Serial"));if(!matches.isEmpty()){n.putUUID("RecipientActor",matches.get(0).getUUID());for(int i=1;i<matches.size();i++)matches.get(i).discard();return matches.get(0);}var r=SecretWorld.realm(p);var actor=(Math.floorMod(n.getLong("DeliverySeed"),2)==0?ModEntities.MOM:ModEntities.DAD).get().create(l);if(actor==null)return null;actor.deliveryResident(true);actor.makeOtherParent(Math.floorMod((int)n.getLong("DeliverySeed"),4));actor.getPersistentData().putUUID("RealmDoor",s.door);actor.getPersistentData().putInt("RealmGeneration",r.parentGeneration);actor.getPersistentData().putUUID("DeliveryOwner",p.getUUID());actor.getPersistentData().putInt("DeliverySerial",n.getInt("Serial"));actor.getPersistentData().putLong("DeliveryHome",c.asLong());actor.setCustomName(Component.literal(new String[]{"Mrs. Hawthorn","Mr. Thimble","Mrs. Poppy","Mr. Reed"}[Math.floorMod((int)n.getLong("DeliverySeed"),4)]));actor.eventGaze(true);actor.setPos(Vec3.atBottomCenterOf(c));l.addFreshEntity(actor);n.putUUID("RecipientActor",actor.getUUID());return actor;}
    public static boolean residentControl(ParentEntity actor){if(!actor.getPersistentData().hasUUID("DeliveryOwner"))return false;actor.deliveryResident(true);var id=actor.getPersistentData().getUUID("DeliveryOwner");var s=VisitData.get(actor.getServer()).scenes.get(id);if(s==null||VisitEvents.type(s)!=VisitEvents.Type.SPECIAL_DELIVERY||!s.loop.event.getBoolean("DeliveryPending")||actor.getPersistentData().getInt("DeliverySerial")!=s.loop.event.getInt("Serial")){actor.discard();return true;}var p=actor.getServer().getPlayerList().getPlayer(id);if(p==null||p.level()!=actor.level()){actor.getNavigation().stop();return true;}var n=s.loop.event;if(n.contains("KnockAt")){long elapsed=OtherMotherLoop.now(p)-n.getLong("KnockAt");if(elapsed>=30){setDoor(p,s,true);var target=Vec3.atBottomCenterOf(DeliveryRoute.door(s).south());if(actor.distanceToSqr(target)>1&&actor.tickCount%20==0)actor.getNavigation().moveTo(target.x,target.y,target.z,.8);else actor.lookAtStoryPlayer(p);}}else if(actor.tickCount%240==0){var c=DeliveryRoute.house(s);actor.getNavigation().moveTo(c.getX()+.5+(p.getRandom().nextBoolean()?1:-1),c.getY(),c.getZ()+.5,.6);}if(n.getBoolean("DeliveryDelivered")&&OtherMotherLoop.now(p)>n.getLong("ReceivedAt")+60)actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);return true;}
    static void setDoor(ServerPlayer p,VisitData.Scene s,boolean open){var at=DeliveryRoute.door(s);var level=p.server.getLevel(OtherWorld.KEY);if(at==null||level==null)return;for(int dy=0;dy<2;dy++){var state=level.getBlockState(at.above(dy));if(state.is(Blocks.SPRUCE_DOOR))level.setBlock(at.above(dy),state.setValue(DoorBlock.OPEN,open),2);}}
    public static boolean recipientInteract(ServerPlayer p,ParentEntity actor){if(!actor.getPersistentData().hasUUID("DeliveryOwner"))return false;var s=OtherMotherLoop.active(p);if(s==null||!p.getUUID().equals(actor.getPersistentData().getUUID("DeliveryOwner"))||VisitEvents.type(s)!=VisitEvents.Type.SPECIAL_DELIVERY||s.loop.phase!=DELIVERY_ACTIVE||s.loop.secrets.searching()||!s.loop.event.hasUUID("RecipientActor")||!s.loop.event.getUUID("RecipientActor").equals(actor.getUUID())||actor.distanceToSqr(p)>25)return true;var n=s.loop.event;if(n.getBoolean("DeliveryOpened")){VisitAudio.caption(p,actor.getName().getString(),"I was expecting a sealed parcel. Perhaps you should head home.",80);return true;}if(n.getBoolean("DeliveryDelivered"))return true;if(!n.contains("KnockAt")||OtherMotherLoop.now(p)-n.getLong("KnockAt")<30)return true;boolean found=false;for(int i=0;i<p.getInventory().getContainerSize();i++)if(valid(p,s,p.getInventory().getItem(i)))found=true;if(!found)return true;var received=parcel(p,s);n.putBoolean("DeliveryDelivered",true);n.putLong("ReceivedAt",OtherMotherLoop.now(p));n.putString("DeliveryState","RETURNING");removePackage(p);actor.setItemInHand(InteractionHand.MAIN_HAND,received);actor.swing(InteractionHand.MAIN_HAND);VisitAudio.caption(p,actor.getName().getString(),"Ah, you must be the delivery! Thank you kindly. You'd best head back now.",100);SecretTransactions.checkpoint(p);return true;}
    public static boolean motherInteract(ServerPlayer p,ParentEntity m){if(!active(p)||m!=MotherSearch.mother(p)||m.distanceToSqr(p)>36)return false;var s=OtherMotherLoop.scene(p);var n=s.loop.event;if(s.loop.phase!=DELIVERY_ACTIVE||s.loop.secrets.searching()||SecretDialogue.busy(p))return true;if(n.getBoolean("DeliveryOpened")||n.getBoolean("DeliveryDelivered")){if(n.getBoolean("DeliveryKnown"))return true;finish(p,s);}else if(p.isShiftKeyDown()){n.putBoolean("DeliveryCancelled",true);n.putBoolean("DeliveryPending",false);VisitEvents.next(p,s,true);}else VisitAudio.caption(p,"Other Mother","Follow the path, deliver the package, and come back to me, sweetheart.",75);return true;}
    static void finish(ServerPlayer p,VisitData.Scene s){s.loop.event.putString("DeliveryState","RETURNING");OtherMotherLoop.phase(p,s,DELIVERY_FINISH);}
    public static boolean caught(ServerPlayer p,OtherMotherWelcome.State state,Set<String> evidence){if(!openedActive(p))return false;var mother=MotherSearch.mother(p);if(mother==null||!mother.getBoundingBox().inflate(.08,0,.08).intersects(p.getBoundingBox())||!mother.hasLineOfSight(p))return false;var s=OtherMotherLoop.scene(p);var n=s.loop.event;if(n.getBoolean("DeliveryKnown"))return false;n.putBoolean("DeliveryKnown",true);n.putString("DeliveryState","BETRAYAL_DISCOVERED");double severity=SecretRegistry.ALL.get(n.getString("DeliveryPayload")).severity();s.loop.secrets.deliveryBetrayals.add(n.getUUID("DeliveryId").toString());s.loop.secrets.exposed.addAll(evidence);OtherMotherLoop.relationship(p,s.loop.trust-(float)(VisitConfig.DELIVERY_CAUGHT_TRUST.get()+severity*.05),s.loop.suspicion+(float)(VisitConfig.DELIVERY_CAUGHT_SUSPICION.get()+severity*.10));s.loop.secrets.search=SecretsState.Search.NORMAL;s.loop.secrets.world.putLong("CatchUntil",OtherMotherLoop.now(p)+200);SecretDialogue.confront(p,SecretDialogue.Event.DELIVERY_OPENED,state);SecretTransactions.checkpoint(p);return true;}
    public static boolean resume(ServerPlayer p){var s=OtherMotherLoop.scene(p);if(s==null||VisitEvents.type(s)!=VisitEvents.Type.SPECIAL_DELIVERY||!s.loop.event.getBoolean("DeliveryPending"))return false;var n=s.loop.event;if(n.getBoolean("DeliveryKnown")){n.putBoolean("DeliveryResolved",true);n.putBoolean("DeliveryPending",false);VisitEvents.next(p,s,false);}else{OtherMotherLoop.phase(p,s,DELIVERY_ACTIVE);ensurePackage(p,s);}return true;}
    static void cleanup(ServerPlayer p,VisitData.Scene s){if(s.loop.event.hasUUID("RecipientActor")){var l=p.server.getLevel(OtherWorld.KEY);var actor=l==null?null:l.getEntity(s.loop.event.getUUID("RecipientActor"));if(actor!=null)actor.discard();}if(VisitEvents.type(s)==VisitEvents.Type.SPECIAL_DELIVERY){setDoor(p,s,false);removePackage(p);}DeliveryRoute.cleanup(p,s);ROUTES.remove(p.getUUID());for(String key:List.of("DeliveryId","DeliveryRecipient","DeliverySeed","DeliveryPayload","DeliveryPending","DeliveryState","DeliveryVisit","DeliveryElapsed","DeliveryCancelled","DeliveryOpened","DeliveryDelivered","DeliveryKnown","DeliveryResolved","DeliverySecretIssued","DeliveryProtected","DeliveryWarning","DeliveryAwaitRelease","DeliveryClickAfter","PackageGranted","RouteHintAfter","RecipientActor","KnockAt","ReceivedAt"))s.loop.event.remove(key);}
    public static boolean blockedContainerClick(AbstractContainerMenu menu,int slot,int button,ClickType type,Player player){if(!(player instanceof ServerPlayer))return false;var carried=menu.getCarried();ItemStack target=slot>=0&&slot<menu.slots.size()?menu.slots.get(slot).getItem():ItemStack.EMPTY;boolean packageItem=carried.is(PACKAGE.get())||target.is(PACKAGE.get());if(type==ClickType.SWAP&&button>=0&&button<player.getInventory().getContainerSize())packageItem|=player.getInventory().getItem(button).is(PACKAGE.get());if(!packageItem)return false;if(type==ClickType.QUICK_MOVE||type==ClickType.THROW||type==ClickType.QUICK_CRAFT)return true;return slot<0||slot>=menu.slots.size()||!(menu.slots.get(slot).container instanceof Inventory);}
    @net.minecraftforge.eventbus.api.SubscribeEvent(priority=net.minecraftforge.eventbus.api.EventPriority.HIGHEST) public static void knock(net.minecraftforge.event.entity.player.PlayerInteractEvent.RightClickBlock e){if(!(e.getEntity() instanceof ServerPlayer p)||e.getHand()!=InteractionHand.MAIN_HAND||!active(p))return;var s=OtherMotherLoop.scene(p);var door=DeliveryRoute.door(s);if(door==null||!e.getPos().equals(door)&&!e.getPos().equals(door.above())||s.loop.phase!=DELIVERY_ACTIVE)return;e.setCanceled(true);e.setCancellationResult(InteractionResult.SUCCESS);var n=s.loop.event;if(!n.contains("KnockAt")){n.putLong("KnockAt",OtherMotherLoop.now(p));p.serverLevel().playSound(null,door,net.minecraft.sounds.SoundEvents.WOOD_HIT,net.minecraft.sounds.SoundSource.BLOCKS,.6F,.75F);p.displayClientMessage(Component.literal("Someone is coming to the door."),true);}SecretTransactions.checkpoint(p);}
    @net.minecraftforge.eventbus.api.SubscribeEvent public static void toss(net.minecraftforge.event.entity.item.ItemTossEvent e){if(e.getPlayer() instanceof ServerPlayer p&&e.getEntity().getItem().is(PACKAGE.get())){e.setCanceled(true);e.getEntity().discard();var s=OtherMotherLoop.scene(p);if(s!=null)ensurePackage(p,s);}}
    @net.minecraftforge.eventbus.api.SubscribeEvent public static void pickup(net.minecraftforge.event.entity.player.EntityItemPickupEvent e){if(e.getItem().getItem().is(PACKAGE.get()))e.setCanceled(true);}
    /** Operator-only diagnostics; these controls never bypass ordinary player ownership. */
    public static void debug(ServerPlayer p,String action){
        if(!p.hasPermissions(2)||!OtherWorld.isOther(p.level()))return;
        var s=OtherMotherLoop.active(p);if(s==null)return;var parts=action.split(",",2);String arg=parts.length>1?parts[1]:"";
        if(parts[0].equals("force")){VisitEvents.start(p,s,VisitEvents.Type.SPECIAL_DELIVERY);return;}
        if(parts[0].equals("voice")){try{int i=Integer.parseInt(arg);if(i>=0&&i<30)VisitAudio.play(p,pools().get(i/2).sound(i%2),false);}catch(NumberFormatException ignored){}return;}
        if(VisitEvents.type(s)!=VisitEvents.Type.SPECIAL_DELIVERY)return;var n=s.loop.event;
        switch(parts[0]){
            case "state"->p.sendSystemMessage(Component.literal(n.toString()));
            case "protection"->p.sendSystemMessage(Component.literal("Protected: "+protectedRoute(p)+"; route distance: "+distance(p,s)));
            case "destination"->{var at=DeliveryRoute.house(s);if(at!=null)p.teleportTo(p.serverLevel(),at.getX()+.5,at.getY(),at.getZ()-5.5,p.getYRot(),0);}
            case "window"->{if(!DeliveryRoute.nodes(s).isEmpty()&&n.getInt("DeliveryBuildCursor")>=n.getList("DeliveryBuild",10).size())begin(p,s);}
            case "package"->ensurePackage(p,s);
            case "resume"->resume(p);
            case "cancel"->{n.putBoolean("DeliveryPending",false);VisitEvents.next(p,s,true);}
            default->{}
        }
        OtherMotherLoop.changed(p);
    }
    public static void clearCaches(){ROUTES.clear();DeliveryRoute.clearSearches();}
    private SpecialDelivery(){}
}
